    #[test]
    fn resolve_egress_nat_config_validates_iface_names() {
        // ACCEPT: real Linux iface names — VLAN '.', bridge/bond '-', predictable
        // (ens/enp), wireguard/tun, and a full 15-char name at the IFNAMSIZ cap.
        for name in [
            "eth0",
            "eth1",
            "ens5",
            "enp3s0",
            "enp0s3",
            "wlan0",
            "br-lan",
            "eth0.100",
            "bond0",
            "wg0",
            "tun0",
            "abcdef123456789", // 15 chars
        ] {
            let mut w = egress_section(true);
            w.wan_iface = Some(name.to_string());
            w.lan_iface = Some("zz9".to_string()); // keep lan != wan (guarded separately)
            assert!(
                resolve_egress_nat_config(&w).is_ok(),
                "wan_iface should accept {name:?}"
            );
            let mut l = egress_section(true);
            l.lan_iface = Some(name.to_string());
            l.wan_iface = Some("zz8".to_string()); // keep wan != lan (guarded separately)
            assert!(
                resolve_egress_nat_config(&l).is_ok(),
                "lan_iface should accept {name:?}"
            );
        }

        // REJECT: empty, over-length, and every injection metacharacter class
        // (shell F7, nft F12, YAML F13), checked on BOTH fields independently.
        for bad in [
            "",
            "abcdef1234567890",     // 16 chars > IFNAMSIZ-1
            "eth0$(reboot)",        // shell: $( )
            "eth0`id`",             // shell: backtick
            "eth0;reboot",          // shell: ;
            "eth0 reboot",          // shell: space
            "eth0|x",               // shell: |
            "eth0&",                // shell: &
            "eth0>x",               // shell: >
            "eth0\"",               // nft / yaml token break
            "eth0\\",               // shell backslash
            "eth0\nenabled: false", // yaml newline / F13
            "eth0/../x",            // path / slash
            "eth\t0",               // internal tab (leading/trailing ws is trimmed upstream)
            ".",
            "..",
        ] {
            let mut w = egress_section(true);
            w.wan_iface = Some(bad.to_string());
            assert!(
                resolve_egress_nat_config(&w).is_err(),
                "wan_iface should reject {bad:?}"
            );
            let mut l = egress_section(true);
            l.lan_iface = Some(bad.to_string());
            assert!(
                resolve_egress_nat_config(&l).is_err(),
                "lan_iface should reject {bad:?}"
            );
        }
    }

    #[test]
    fn f3_hive_id_traversal_is_rejected() {
        // valid_hive_id (now run FIRST in both add flows) forbids every char
        // that could escape hives_root via join: '/', '.', '..'.
        for bad in [
            "",
            "..",
            ".",
            "../victim",
            "a/b",
            "a.b",
            "../../etc",
            "foo/../bar",
            "a\0b",
            "héllo",
        ] {
            assert!(!valid_hive_id(bad), "hive_id {bad:?} must be rejected");
        }
        for ok in ["motherbee", "worker1", "hive-01", "a_b-c", "H99"] {
            assert!(valid_hive_id(ok), "hive_id {ok:?} must be accepted");
        }

        // Defense-in-depth backstop: only a direct child of root may be deleted.
        let root = Path::new("/var/lib/fluxbee/storage/hives");
        assert!(hive_dir_is_direct_child(&root.join("worker1"), root));
        assert!(hive_dir_is_direct_child(&root.join("hive-01"), root));
        // Escapes / non-children are refused even if they lexically "start with" root.
        assert!(!hive_dir_is_direct_child(&root.join("../victim"), root));
        assert!(!hive_dir_is_direct_child(&root.join("a").join("b"), root));
        assert!(!hive_dir_is_direct_child(root, root)); // root itself, no child component
        assert!(!hive_dir_is_direct_child(Path::new("/etc/passwd"), root));
    }

    #[test]
    fn egress_nft_ruleset_is_deterministic_and_substituted() {
        let cfg = resolve_egress_nat_config(&egress_section(true)).unwrap();
        let a = egress_nft_ruleset(&cfg);
        let b = egress_nft_ruleset(&cfg);
        assert_eq!(
            a, b,
            "ruleset must be deterministic for idempotent re-apply"
        );
        assert!(a.contains("table inet fluxbee_egress"));
        // SO-08: self-flushing atomic apply (add + flush + define) — no separate
        // delete step, so no window where forwarding is on but the table is gone.
        assert!(a.contains("add table inet fluxbee_egress"));
        assert!(a.contains("flush table inet fluxbee_egress"));
        assert!(!a.contains("delete table inet fluxbee_egress"));
        assert!(a.contains("ip saddr 192.168.8.0/24 oifname \"eth0\" masquerade"));
        assert!(a.contains("iifname \"eth1\" oifname \"eth0\" ip saddr 192.168.8.0/24 accept"));
        assert!(a.contains("meta nfproto ipv6 drop"));
    }

